 46|   setRate(rateCentsPerHour: number): { rateCentsPerHour: number } {
 47|     if (!Number.isInteger(rateCentsPerHour) || rateCentsPerHour < 0) {
 48|       throw new DomainError("validation", "rateCentsPerHour must be a non-negative integer");
 49|     }
 50|     this.club.setRate(rateCentsPerHour);
 51|     return { rateCentsPerHour };
 52|   }
