 58|   book(input: NewClubBookingInput): ClubBooking & { rink: "whole" | "half" } {
 59|     if (!DATE_RE.test(input.date)) throw new DomainError("validation", "date must be YYYY-MM-DD");
 60|     if (!TIME_RE.test(input.start) || !TIME_RE.test(input.end)) {
 61|       throw new DomainError("validation", "start and end must be HH:MM");
 62|     }
 63|     if (input.end <= input.start) throw new DomainError("validation", "end must be after start");
 64|     let halves: Half[];
 65|     if (input.rink === "whole") {
 66|       halves = ["a", "b"];
 67|     } else if (input.rink === "half") {
 68|       if (input.half !== "a" && input.half !== "b") {
 69|         throw new DomainError("validation", "half must be \"a\" or \"b\" for a half rink");
 70|       }
 71|       halves = [input.half];
 72|     } else {
 73|       throw new DomainError("validation", "rink must be \"whole\" or \"half\"");
 74|     }
 75|     for (const other of this.club.listByDate(input.date)) {
 76|       if (overlaps(input, other) && other.halves.some((h) => halves.includes(h))) {
 77|         throw new DomainError("conflict", "overlaps another club booking on the same half");
 78|       }
 79|     }
 80|     const booking = this.club.create({
 81|       date: input.date,
 82|       start: input.start,
 83|       end: input.end,
 84|       halves,
 85|       rateCentsPerHour: this.club.getRate(),
 86|     });
 87|     return { ...booking, rink: rinkOf(booking) };
 88|   }
 89| 
 90|   list(): Array<ClubBooking & { rink: "whole" | "half" }> {
 91|     return this.club.list().map((b) => ({ ...b, rink: rinkOf(b) }));
 92|   }
