 94|   /** Monthly invoice: hours at the club rate; a half rink is charged at half the rate. */
 95|   invoice(month: string): ClubInvoice {
 96|     if (!MONTH_RE.test(month)) throw new DomainError("validation", "month must be YYYY-MM");
 97|     const lines: InvoiceLine[] = this.club.listByMonth(month).map((b) => {
 98|       const hours = minutesBetween(b.start, b.end) / 60;
 99|       const share = b.halves.length / 2;
100|       return {
101|         bookingId: b.id,
102|         date: b.date,
103|         start: b.start,
104|         end: b.end,
105|         rink: rinkOf(b),
106|         half: b.halves.length === 1 ? b.halves[0] : undefined,
107|         hours,
108|         amountCents: Math.round(hours * share * b.rateCentsPerHour),
109|       };
110|     });
111|     return {
112|       month,
113|       rateCentsPerHour: this.club.getRate(),
114|       lines,
115|       totalHours: lines.reduce((n, l) => n + l.hours, 0),
116|       totalCents: lines.reduce((n, l) => n + l.amountCents, 0),
117|     };
118|   }
